package org.novasos.healthysv2.messaging;
import static org.novasos.healthysv2.messaging.api.MessagingDtos.*;import java.net.*;import java.util.*;import jakarta.validation.Valid;import io.swagger.v3.oas.annotations.tags.Tag;import org.novasos.healthysv2.shared.api.ApiPaths;import org.novasos.healthysv2.shared.api.dto.PageResponse;import org.springframework.data.domain.Pageable;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping(ApiPaths.V1+"/conversations") @Tag(name="Messaging",description="Secure conversations, participants, messages and read receipts") @PreAuthorize("hasAnyRole('PLATFORM_ADMIN','HOSPITAL_ADMIN','HOSPITAL_AGENT','DOCTOR','NURSE','PHARMACIST','LAB_TECHNICIAN','PATIENT')") class ConversationController{
 private final ConversationService service;ConversationController(ConversationService service){this.service=service;}
 @PostMapping ResponseEntity<ConversationResponse>create(@Valid@RequestBody CreateConversationRequest r){var out=service.create(r);return ResponseEntity.created(URI.create(ApiPaths.V1+"/conversations/"+out.id())).body(out);}@GetMapping PageResponse<ConversationSummary>list(Pageable pageable){return service.list(pageable);}@GetMapping("/{id}")ConversationResponse find(@PathVariable UUID id){return service.find(id);}@GetMapping("/{id}/messages")PageResponse<MessageResponse>messages(@PathVariable UUID id,Pageable pageable){return service.messages(id,pageable);}@PostMapping("/{id}/messages")ResponseEntity<MessageResponse>send(@PathVariable UUID id,@Valid@RequestBody SendMessageRequest r){return ResponseEntity.status(201).body(service.send(id,r));}@PostMapping("/{id}/participants")ConversationResponse participant(@PathVariable UUID id,@Valid@RequestBody AddParticipantRequest r){return service.addParticipant(id,r);}@PostMapping("/messages/{id}/read")ReadReceiptResponse read(@PathVariable UUID id){return service.markRead(id);}
}
